import React, { useState, useRef, use } from 'react';
import './styles/App.css';
import PostList from './components/PostList';
import MyButton from './components/UI/button/MyButton';
import MyInput from './components/UI/input/MyInput';
import PostForm from './components/PostForm';
import MySelect from './components/UI/select/MySelect';

function App() {
  const [posts, setPosts] = useState([
    { id: 1, title: 'Javascript', body: 'Description' },
    { id: 2, title: 'Javascript 2', body: 'Description' },
    { id: 3, title: 'Javascript 3', body: 'Description' },
  ]);

  const [selectedSort, setSelectedSort] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const sortedPosts = [...posts].sort((a, b) => a[sort].localeCompare(b[sort]));
  [...posts].sort((a, b) => a[sort].localeCompare(b[sort]));

  const createPost = newPost => {
    setPosts([...posts, newPost]);
  };

  //Отримуємо post з дочірнього компоненту
  const removePost = post => {
    setPosts(posts.filter(p => p.id !== post.id));
  };

  const sortPosts = sort => {
    setSelectedSort(sort);
    setPosts();
  };
  return (
    <div className='App'>
      <PostForm create={createPost} />
      <hr style={{ margin: '15px 0' }} />
      <div>
        <MyInput
          value={searchQuery}
          onChage={e => setSearchQuery(e.target.value)}
          placeholder='Search'
        />
        <MySelect
          value={selectedSort}
          onChange={sortPosts}
          defaultValue='Sort by'
          options={[
            { value: 'title', name: 'By title' },
            { value: 'body', name: 'By description' },
          ]}
        />
      </div>
      {posts.length !== 0 ? (
        <PostList
          remove={removePost}
          posts={posts}
          title='Posts about JavaScript'
        />
      ) : (
        <h1 style={{ textAlign: 'center' }}>No posts found</h1>
      )}
    </div>
  );
}

export default App;
